<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {foundation,teachingApi,type Asset,type Assessment} from '@/api/foundation'
import {messageOf} from '@/api/client'
import type {ChatResult,Citation} from '@/api/types'
import SafeAnswer from '@/components/SafeAnswer.vue'
import SpeakButton from '@/components/SpeakButton.vue'
import CitationReader from '@/components/CitationReader.vue'
const props=defineProps<{pointId:string;question:Asset}>(),emit=defineEmits<{answered:[]}>()
const assessment=ref<Assessment|null>(null),choice=ref<number|null>(null),busy=ref(false),error=ref(''),feedback=ref<ChatResult|null>(null),explaining=ref(false),explainError=ref(''),source=ref<Citation|null>(null)
const result=computed(()=>assessment.value?.Result?.Items[0]);let version=0
async function explain(){if(!assessment.value?.Result)return;const id=version;explaining.value=true;explainError.value='';try{const response=await teachingApi.explainExample(assessment.value.ID);if(id===version)feedback.value=response}catch(e){if(id===version)explainError.value='逐步讲解暂未完成，先核对原文解析：'+messageOf(e)}finally{if(id===version)explaining.value=false}}
async function load(){const id=++version;busy.value=true;error.value='';assessment.value=null;feedback.value=null;choice.value=null;source.value=null;explainError.value='';explaining.value=false;try{const response=await teachingApi.example(props.pointId,props.question);if(id!==version)return;assessment.value=response.Assessment;choice.value=response.Assessment?.Result?.Items[0]?.Selected??null;if(response.Assessment?.Result)explain()}catch(e){if(id===version)error.value=messageOf(e)}finally{if(id===version)busy.value=false}}
watch(()=>`${props.pointId}:${props.question.ID}:${props.question.Revision}`,load,{immediate:true});onBeforeUnmount(()=>version++)
async function submit(){if(choice.value===null)return;const id=version;busy.value=true;error.value='';try{const a=assessment.value??await teachingApi.startExample(props.pointId,props.question);if(id!==version)return;assessment.value=a;const response=await foundation.submit(a.ID,{[a.Questions[0].ID]:choice.value});if(id!==version)return;assessment.value.Result=response;emit('answered');explain()}catch(e){if(id===version)error.value=messageOf(e)}finally{if(id===version)busy.value=false}}
async function retry(){const id=version;busy.value=true;error.value='';try{const a=await teachingApi.startExample(props.pointId,props.question,true);if(id!==version)return;assessment.value=a;feedback.value=null;choice.value=null;explainError.value=''}catch(e){if(id===version)error.value=messageOf(e)}finally{if(id===version)busy.value=false}}
function original(){const q=props.question;if(q.Payload.DocumentID)source.value={DocumentID:q.Payload.DocumentID,DocumentTitle:q.Payload.Source,ChunkID:'',Page:q.Payload.Page,Location:q.Payload.Page?`第${q.Payload.Page}页`:'例题来源',Excerpt:q.Payload.Stem,Score:1}}
</script>
<template><section class="example-exercise" aria-label="例题作答与讲解"><p class="stem">{{question.Payload.Stem}}</p><img v-for="(img,n) in question.Payload.Images??[]" :key="n" :src="img" alt="例题原图"/><form v-if="!result" @submit.prevent="submit"><fieldset :disabled="busy"><legend>先独立选择，再看答案与讲解</legend><label v-for="(option,n) in question.Payload.Options" :key="n"><input v-model="choice" type="radio" :value="n" :name="`example-${pointId}-${question.ID}`" required/>{{String.fromCharCode(65+n)}}. {{option}}</label><label><input v-model="choice" type="radio" :value="-1" :name="`example-${pointId}-${question.ID}`" required/>暂时不会，请带我分析</label></fieldset><button class="primary" :disabled="busy||choice===null">{{busy?'正在保存…':'提交例题并看讲解'}}</button></form><div v-else class="example-feedback"><h4>{{result.Correct?'这道例题答对了，继续核对理由。':'这道例题需要复查，已记录到你的学情。'}}</h4><p>你的答案：{{result.Selected<0?'暂时不会':String.fromCharCode(65+result.Selected)}} · 参考答案：{{String.fromCharCode(65+result.Answer)}}</p><p v-if="!result.Correct">先看哪些题目条件与定义对应；随后用不同题组检查，不能只记答案。<RouterLink :to="{path:'/exam408/weakness',query:{point:question.PointID}}">查看本知识点的复习依据 →</RouterLink></p><p v-if="explaining" role="status">作答已保存，老师正在整理逐步讲解…</p><p v-if="explainError" class="muted">{{explainError}} <button class="secondary" :disabled="explaining" @click="explain">重试老师讲解</button></p><p v-if="!feedback" class="muted">原文参考解析</p><SafeAnswer :text="feedback?.Answer??result.Explanation" :citations="feedback?.Sources.length??0" @cite="n=>source=feedback!.Sources[n]??null"/><SpeakButton :text="feedback?.Answer??result.Explanation"/><details v-if="feedback?.Sources.length"><summary>讲解依据</summary><button v-for="(c,n) in feedback.Sources" :key="n" class="secondary" @click="source=c">{{c.DocumentTitle}} · {{c.Location}}</button></details><button class="secondary" :disabled="busy||explaining" @click="retry">再作答一次</button><p class="muted">同题反复作答不增加独立题组数；看过解析后的再答不能代替新题复测。</p></div><p v-if="error" class="notice error" role="alert">{{error}}</p><small>{{question.Payload.Source}}</small><button v-if="result&&question.Payload.DocumentID" class="secondary" @click="original">查看例题原文</button><CitationReader :source="source" @close="source=null"/></section></template>
<style scoped>.example-exercise{min-width:0;overflow-wrap:anywhere}.stem{white-space:pre-wrap;line-height:1.9}.example-exercise fieldset{border:1px solid #dbeafe;border-radius:10px;margin:16px 0;padding:12px}.example-exercise label{display:flex;gap:10px;align-items:baseline;padding:10px 0}.example-exercise input{width:auto;flex-shrink:0}.example-exercise img{max-width:100%;max-height:400px;object-fit:contain}.example-feedback{padding:16px;border:1px solid #dbeafe;background:#f8fafc;border-radius:12px;margin:16px 0}.example-feedback h4{margin-top:0}.example-exercise .secondary{margin:8px 8px 0 0;max-width:100%}</style>
